from pathlib import Path
p=Path('/mnt/data/v55/web/index.html')
s=p.read_text(encoding='utf-8')
css=r'''<style id="v54-ultra-visual-css">
.v54-overlay{position:fixed;inset:0;background:rgba(3,8,18,.78);backdrop-filter:blur(8px);z-index:99999;display:none;align-items:center;justify-content:center;padding:18px}.v54-overlay.show{display:flex}.v54-modal{width:min(1180px,96vw);max-height:94vh;overflow:auto;background:#0b1220;color:#e8eef8;border:1px solid #26354d;border-radius:22px;box-shadow:0 30px 100px #0008}.v54-head{position:sticky;top:0;z-index:2;padding:18px 22px;border-bottom:1px solid #26354d;background:#0b1220ee;backdrop-filter:blur(12px);display:flex;justify-content:space-between}.v54-kicker{font-size:11px;letter-spacing:.14em;text-transform:uppercase;opacity:.65}.v54-close{border:0;background:#172238;color:#fff;border-radius:12px;font-size:26px;width:42px;height:42px;cursor:pointer}.v54-tabs{display:flex;gap:7px;padding:12px 18px;border-bottom:1px solid #26354d;overflow:auto}.v54-tab{border:1px solid #2b3b54;background:#111b2d;color:#cbd7e8;padding:9px 13px;border-radius:10px;cursor:pointer;white-space:nowrap}.v54-tab.active{background:#243957;color:#fff}.v54-body{padding:18px}.v54-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:14px}.v54-card{background:#101a2b;border:1px solid #24344d;border-radius:16px;padding:15px}.v54-chart{height:260px;position:relative}.v54-chart svg{width:100%;height:100%}.v54-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.v54-kpi{background:#0c1524;border:1px solid #22334b;border-radius:12px;padding:12px}.v54-kpi small{display:block;opacity:.65}.v54-kpi b{font-size:23px}.v54-bars{display:flex;align-items:flex-end;gap:8px;height:190px;padding:12px}.v54-bar{flex:1;border-radius:7px 7px 2px 2px;background:linear-gradient(180deg,#6aa5ff,#315c9e);min-width:10px;animation:v54grow .8s ease both}.v54-donut{width:170px;height:170px;border-radius:50%;margin:auto;display:grid;place-items:center;background:conic-gradient(#6aa5ff 0 42%,#55c7a4 42% 69%,#f0b65a 69% 84%,#ef6b73 84% 100%);position:relative}.v54-donut:after{content:'';width:92px;height:92px;border-radius:50%;background:#101a2b;position:absolute}.v54-donut span{z-index:1;font-weight:800}.v54-table{width:100%;border-collapse:collapse;font-size:13px}.v54-table th,.v54-table td{padding:9px;border-bottom:1px solid #233149;text-align:left}.v54-badge{display:inline-block;padding:3px 7px;border-radius:99px;background:#173a32;color:#8fe0c4;font-size:11px}.v54-timeline{display:grid;gap:8px}.v54-event{display:flex;gap:10px;align-items:flex-start}.v54-event i{width:10px;height:10px;border-radius:50%;background:#65a9ff;margin-top:5px;box-shadow:0 0 12px #65a9ff}.v54-live{animation:v54pulse 1.6s infinite}.v54-skeleton{height:10px;border-radius:5px;background:linear-gradient(90deg,#17243a,#2a3c59,#17243a);background-size:200% 100%;animation:v54shimmer 1s linear infinite}.v54-action{cursor:pointer;transition:.18s}.v54-action:hover{transform:translateY(-2px);border-color:#5279a9;box-shadow:0 8px 24px #0003}.v54-toast{position:fixed;right:22px;bottom:22px;z-index:100001;background:#111d30;color:#fff;border:1px solid #334b6d;border-radius:12px;padding:12px 16px;box-shadow:0 12px 35px #0006}.v54-progress{height:7px;background:#17243a;border-radius:99px;overflow:hidden}.v54-progress i{display:block;height:100%;width:0;background:#6aa5ff;animation:v54prog 1.8s ease forwards}.v54-mini{font-size:12px;opacity:.72}.v54-two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.v54-radar{height:220px}.v54-radar svg{width:100%;height:100%}@keyframes v54grow{from{height:3px;opacity:.2}to{opacity:1}}@keyframes v54pulse{50%{opacity:.55}}@keyframes v54shimmer{to{background-position:-200% 0}}@keyframes v54prog{to{width:100%}}@media(max-width:800px){.v54-grid,.v54-two{grid-template-columns:1fr}.v54-kpis{grid-template-columns:repeat(2,1fr)}}
</style>'''
script=r'''<script id="v54-ultra-custom-simulation">
(function(){
 const S=['health','agri','unicef','who','wfp','fao','monitoring']; const N={health:'Ministry of Health',agri:'Ministry of Agriculture',unicef:'UNICEF',who:'WHO',wfp:'WFP',fao:'FAO',monitoring:'Projects, Surveys & Nutrition Surveillance'};let active='fao',subject='Operational intelligence',tab='overview',toastTimer;
 const $=id=>document.getElementById(id); const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
 function root(e){let r=e?.closest?.('.view');return r&&S.includes(r.id)?r:null} function ctx(sec){return {country:$(sec+'Country')?.selectedOptions?.[0]?.textContent||'Togo',level:$(sec+'Level')?.selectedOptions?.[0]?.textContent||'National',year:$(sec+'Year')?.value||'2026'}}
 function seed(sec,sub){let c=ctx(sec);let z=[...sec+sub+c.country+c.year].reduce((a,ch)=>a+ch.charCodeAt(0),0);return z}
 function vals(sec,sub){let z=seed(sec,sub);return [62,71,78,67,84,73,58].map((v,i)=>Math.max(35,Math.min(96,v+(z+i*7)%15-7)))}
 function svgLine(v){let w=620,h=240,p=28, max=100;let pts=v.map((x,i)=>`${p+i*(w-2*p)/(v.length-1)},${h-p-(x/max)*(h-2*p)}`).join(' ');let dots=v.map((x,i)=>`<circle cx="${p+i*(w-2*p)/(v.length-1)}" cy="${h-p-(x/max)*(h-2*p)}" r="4" fill="currentColor"/>`).join('');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="M${pts}" fill="none" stroke="currentColor" stroke-width="4" opacity=".9"/><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="1" opacity=".15"/>${dots}</svg>`}
 function radar(v){let cx=180,cy=105,r=76;let pts=v.slice(0,6).map((x,i)=>{let a=-Math.PI/2+i*Math.PI/3;return `${cx+Math.cos(a)*r*x/100},${cy+Math.sin(a)*r*x/100}`}).join(' ');let grid=[.33,.66,1].map(k=>`<polygon points="${[0,1,2,3,4,5].map(i=>{let a=-Math.PI/2+i*Math.PI/3;return `${cx+Math.cos(a)*r*k},${cy+Math.sin(a)*r*k}`}).join(' ')}" fill="none" stroke="currentColor" opacity=".15"/>`).join('');return `<svg viewBox="0 0 360 210">${grid}<polygon points="${pts}" fill="currentColor" opacity=".2" stroke="currentColor" stroke-width="3"/>${v.slice(0,6).map((x,i)=>{let a=-Math.PI/2+i*Math.PI/3;return `<text x="${cx+Math.cos(a)*95}" y="${cy+Math.sin(a)*95}" text-anchor="middle" font-size="11">${['Coverage','Quality','Risk','Readiness','Equity','Timeliness'][i]}</text>`}).join('')}</svg>`}
 function ensure(){if($('v54Overlay'))return;let d=document.createElement('div');d.id='v54Overlay';d.className='v54-overlay';d.innerHTML=`<div class="v54-modal"><div class="v54-head"><div><div class="v54-kicker">NUTRI.N°1 • Ultra Realistic Investor Simulation</div><h2 id="v54Title">Institutional Intelligence</h2><div id="v54Sub" class="v54-mini"></div></div><button class="v54-close" onclick="NUTRI54.close()">×</button></div><div class="v54-tabs">${[['overview','Overview'],['analytics','Analytics'],['table','Data table'],['gis','GIS & hotspots'],['workflow','Workflow'],['actions','Decision center']].map(x=>`<button class="v54-tab" data-t="${x[0]}">${x[1]}</button>`).join('')}</div><div id="v54Body" class="v54-body"></div></div>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d)NUTRI54.close();let b=e.target.closest('[data-t]');if(b){tab=b.dataset.t)}});}
 function data(){let v=vals(active,subject),c=ctx(active);let labels=active==='fao'?['Production','Yield','Loss control','Market','Food availability','Safety','Climate']:active==='wfp'?['Food security','Affordability','Diversity','Prices','Nutrition','Vulnerability','Early warning']:active==='unicef'?['Stunting','Wasting','Anaemia','Breastfeeding','Diet diversity','Maternal','Coverage']:active==='who'?['Diabetes','Hypertension','Obesity','CVD','Dietary risk','Screening','Prevention']:active==='health'?['Screening','NCD control','Maternal','Child nutrition','Referral','Coverage','Early warning']:active==='agri'?['Production','Inputs','Post-harvest','Markets','Nutrition-sensitive','Safety','Climate']:['Coverage','Target','Data quality','Evaluation','Equity','Timeliness','Completeness'];return {v,labels,c}}
 function table(d){return `<table class="v54-table"><tr><th>Indicator / signal</th><th>Current</th><th>Δ</th><th>Status</th></tr>${d.labels.map((x,i)=>`<tr class="v54-action"><td>${esc(x)}</td><td><b>${d.v[i]}%</b></td><td>${i%2?'−':'+'}${2+i}%</td><td><span class="v54-badge">${d.v[i]>80?'Priority':'Monitored'}</span></td></tr>`).join('')}</table>`}
 function render(){let d=data(),v=d.v,c=d.c;let body='';if(tab==='overview')body=`<div class="v54-kpis">${d.labels.slice(0,4).map((x,i)=>`<div class="v54-kpi v54-action"><small>${x}</small><b>${v[i]}%</b><div class="v54-progress"><i></i></div><div class="v54-mini">Live recalculation</div></div>`).join('')}</div><div class="v54-grid" style="margin-top:14px"><div class="v54-card"><h3>📈 Personalized trend engine</h3><div class="v54-chart">${svgLine(v)}</div><div class="v54-mini">${esc(c.country)} · ${esc(c.level)} · ${esc(c.year)} · simulated signal trajectory</div></div><div class="v54-card"><h3>🎯 System performance profile</h3><div class="v54-radar">${radar(v)}</div></div></div><div class="v54-two" style="margin-top:14px"><div class="v54-card"><h3>🍩 Signal composition</h3><div class="v54-donut"><span>${Math.round(v.reduce((a,b)=>a+b,0)/v.length)}/100</span></div></div><div class="v54-card"><h3>⚡ Live event stream</h3><div class="v54-timeline">${['Context resolved','Data connectors synchronized','Quality gate passed','AI signal fusion completed','Risk model recalculated','Decision output refreshed'].map((x,i)=>`<div class="v54-event"><i class="v54-live"></i><div><b>${x}</b><div class="v54-mini">${new Date(Date.now()-i*21000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})} · ${esc(c.country)}</div></div></div>`).join('')}</div></div></div>`;
 else if(tab==='analytics')body=`<div class="v54-card"><h3>📊 ${esc(subject)} — custom analytics</h3><div class="v54-bars">${v.map((x,i)=>`<i class="v54-bar" style="height:${x}%" title="${esc(d.labels[i])}: ${x}%"></i>`).join('')}</div></div><div class="v54-grid" style="margin-top:14px"><div class="v54-card"><h3>Trend / anomaly curve</h3><div class="v54-chart">${svgLine(v.map((x,i)=>Math.min(98,x+(i%3-1)*7)))}</div></div><div class="v54-card"><h3>Risk decomposition</h3>${d.labels.map((x,i)=>`<div style="margin:9px 0"><div style="display:flex;justify-content:space-between"><span>${x}</span><b>${v[i]}%</b></div><div class="v54-progress"><i style="width:${v[i]}%;animation:none"></i></div></div>`).join('')}</div></div>`;
 else if(tab==='table')body=`<div class="v54-card"><h3>🗃 Live indicator registry</h3>${table(d)}</div>`;
 else if(tab==='gis')body=`<div class="v54-grid"><div class="v54-card"><h3>🗺 ${esc(c.country)} — hotspot intelligence</h3><div style="height:340px;position:relative;background:radial-gradient(circle at 25% 35%,#ef6b7366 0 5%,transparent 6%),radial-gradient(circle at 63% 52%,#f0b65a66 0 7%,transparent 8%),radial-gradient(circle at 78% 25%,#65a9ff66 0 6%,transparent 7%),linear-gradient(135deg,#0d1b2d,#15283c);border-radius:14px;border:1px solid #263b55">${[[25,35,'High'],[63,52,'Watch'],[78,25,'Priority'],[42,73,'Monitor']].map((p,i)=>`<button class="v54-action" style="position:absolute;left:${p[0]}%;top:${p[1]}%;border:0;background:transparent;color:#fff" onclick="NUTRI54.hotspot(${i})">📍<small>${p[2]}</small></button>`).join('')}</div></div><div class="v54-card"><h3>Hotspot ranking</h3>${['Zone A','Zone B','Zone C','Zone D'].map((x,i)=>`<div class="v54-kpi v54-action" style="margin:8px 0"><b>${x}</b><span style="float:right">${v[i+1]}/100</span><div class="v54-mini">Exposure · vulnerability · response gap</div></div>`).join('')}</div></div>`;
 else if(tab==='workflow')body=`<div class="v54-card"><h3>⚙️ Real-time orchestration</h3><div id="v54Flow">${['Authentication','Context engine','Source synchronization','Quality & provenance','AI fusion','Risk / anomaly engine','GIS refresh','Early warning','Decision output','M&E trace'].map((x,i)=>`<div class="v54-event" style="padding:9px;border-bottom:1px solid #223149"><i></i><div style="flex:1"><b>${x}</b><div class="v54-progress"><i style="animation-delay:${i*.12}s"></i></div></div><span class="v54-badge">Queued</span></div>`).join('')}</div></div>`;
 else body=`<div class="v54-grid"><div class="v54-card"><h3>🎯 Decision center</h3><p>Priority score <b>${v[2]}/100</b></p><p>Recommended action: validate the highest-signal hotspot, assign an owner and track outcomes through M&E.</p><button class="btn primary" onclick="NUTRI54.action('Intervention package created')">Create intervention</button> <button class="btn secondary" onclick="NUTRI54.action('Executive brief generated')">Generate brief</button></div><div class="v54-card"><h3>🔐 Traceability</h3><div class="v54-timeline">${['Source provenance','Analytical transformation','Model inference','Decision recommendation','User action'].map(x=>`<div class="v54-event"><i></i><span>${x} <span class="v54-badge">Logged</span></span></div>`).join('')}</div></div></div>`; $('v54Body').innerHTML=body;setTimeout(()=>document.querySelectorAll('.v54-progress i').forEach((x,i)=>{if(!x.style.width)x.style.animationDelay=(i*.08)+'s'}),30)}
 function tab(t){tab=t;render();document.querySelectorAll('.v54-tab').forEach(x=>x.classList.toggle('active',x.dataset.t===t));if(t==='workflow')setTimeout(()=>{document.querySelectorAll('#v54Flow .v54-badge').forEach((x,i)=>setTimeout(()=>x.textContent='Completed',450+i*150))},100)}
 function open(sec,sub){ensure();active=sec;subject=sub||N[sec];tab='overview';$('v54Title').textContent='⚡ '+N[sec]+' — '+subject;$('v54Sub').textContent='LIVE • '+ctx(sec).country+' • '+ctx(sec).level+' • '+ctx(sec).year+' • Front-end demonstration';$('v54Overlay').classList.add('show');render();document.querySelectorAll('.v54-tab').forEach(x=>x.classList.toggle('active',x.dataset.t==='overview'))}
 function action(msg){let t=document.createElement('div');t.className='v54-toast';t.textContent='✓ '+msg;t.onclick=()=>t.remove();document.body.appendChild(t);clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),2600)}
 window.NUTRI54={open,close:()=>{$('v54Overlay')?.classList.remove('show')},action,hotspot:i=>{tab='analytics';action('Hotspot '+(i+1)+' opened — contextual analytics refreshed')}};
 function install(){S.forEach(sec=>{let r=$(sec);if(!r)return;r.querySelectorAll('.card,.inst-kpi,.ncd-card,.age-card,.risk-row,.alert-row,.feeding-row,.maternal-row,.core-card,.rank,.wizard .step,table tr,button:not(.v54-tab):not(.v54-close)').forEach(el=>{if(el.closest('#v54Overlay')||el.closest('.sidebar'))return;el.classList.add('v54-action')})})}
 document.addEventListener('click',e=>{let r=root(e.target);if(!r||e.target.closest('#v54Overlay'))return;if(e.target.closest('.sidebar'))return;let el=e.target.closest('.v54-action');if(el){let t=el.querySelector('h1,h2,h3,b,th,span')?.textContent||el.textContent;NUTRI54.open(r.id,t.trim().slice(0,80));}});document.addEventListener('change',e=>{let r=root(e.target);if(r) setTimeout(()=>NUTRI54.open(r.id,'Context recalculation'),180)});document.addEventListener('keydown',e=>{if(e.key==='Escape')NUTRI54.close()});document.addEventListener('DOMContentLoaded',()=>setTimeout(install,900));new MutationObserver(()=>{clearTimeout(window.__v54i);window.__v54i=setTimeout(install,250)}).observe(document.body,{childList:true,subtree:true});
})();
</script>'''
s=s.replace('</head>',css+'</head>')
s=s.replace('</body>',script+'</body>')
p.write_text(s,encoding='utf-8')
